    if(!lines.length){$('#timetable-feedback').textContent='Add at least one subject or task, one per line.';return}
    const date=$('#timetable-date').value||selectedDate;
    const start=$('#timetable-start').value,end=$('#timetable-end').value,breakMins=+$('#timetable-break').value;
