    const busy=state.sessions.filter(function(s){return s.date===date&&s.source!=='arise-timetable'}).map(function(s){const a=+s.time.slice(0,2)*60+(+s.time.slice(3,5));return {start:a,end:a+(+s.duration||0)}});
