  $('#sudoku-new').addEventListener('click',function(){startSudoku($('#sudoku-difficulty').value,true)});$('#sudoku-difficulty').addEventListener('change',function(){startSudoku(this.value,true)});$('#sudoku-board').addEventListener('click',function(e){const b=e.target.closest('[data-sudoku-cell]');if(b){sudokuGame.selected=+b.dataset.sudokuCell;saveSudoku();renderSudoku()}});$('#sudoku-numpad').addEventListener('click',function(e){const b=e.target.closest('[data-sudoku-num]');if(b)sudokuInput(+b.dataset.sudokuNum)});$('#sudoku-hint').addEventListener('click',sudokuHint);$('#sudoku-check').addEventListener('click',function(){const wrong=sudokuGame.values.some(function(x,i){return x&&x!==sudokuGame.solution[i]}),empty=sudokuGame.values.some(function(x){return !x});$('#sudoku-status').textContent=wrong?'There are entries to review. Check the highlighted squares.':empty?'Everything placed so far matches. Keep filling the board.':'Board complete!';renderSudoku()});$('#sudoku-notes-toggle').addEventListener('click',function(){sudokuNotesMode=!sudokuNotesMode;renderSudoku()});$('#sudoku-clear').addEventListener('click',function(){sudokuInput(0)});document.addEventListener('keydown',function(e){if(!sudokuGame||!$('#view-sudoku').classList.contains('active')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key>='1'&&e.key<='9'){e.preventDefault();sudokuInput(+e.key)}else if(['Backspace','Delete','0'].includes(e.key)){e.preventDefault();sudokuInput(0)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=sudokuGame.selected,r=Math.floor(i/9),c=i%9;sudokuGame.selected=e.key==='ArrowLeft'?r*9+Math.max(0,c-1):e.key==='ArrowRight'?r*9+Math.min(8,c+1):e.key==='ArrowUp'?Math.max(0,r-1)*9+c:Math.min(8,r+1)*9+c;renderSudoku()}});
